const rules:Record<Bucket,string>={circles:'关闭停止新发帖和推荐，合法原帖保留。移出只解除圈子关联，不删除正文；重新开放不恢复撤下的推荐。置顶按运营顺序，普通帖按首次公开时间。',topics:'草稿不影响公开配置。只引用公开可见内容，失效引用停止公开展示，恢复内容后需重新选择。推荐顺序由后台维护。',taxonomy:'PC与手机共用同一分类身份、顺序和配置。简称只改变显示。停用停止新增选择，历史内容保留；合并明确迁移归属，不改变内容类型。',features:'首页爆款只配置作品入选；PC交流推荐、应用顺序、应用Banner及搜索默认独立维护顺序。空配置隐藏，移动端交流按首次公开时间倒序。',slots:'按首页、AI应用页、搜索页管理固定展示位。首页只维护Banner与金刚区，首页四个专题位置由专题排序控制。应用Banner维护图片和关联应用；搜索页维护专题推荐、应用推荐与推荐词。排序值小的优先，同位置不可重复添加。仅已上架且目标公开有效的内容展示，空配置隐藏。首页爆款由作品管理驱动，不另设帖子推荐和应用排序。',events:'实际资格、有效事件与计数由服务端核验，满足条件自动发奖，无领取步骤。结束时刻不包含，结束停止新参与/投稿。活动开始后规则变化先人工核对受影响用户。',submissions:'资格、评审和奖励独立。接受材料保留；本人公开作品可追加多活动，同活动同一期去重，首次发布不得早于活动开始。下架不自动追回已到账积分，要求公开的任务发奖前重校验，结束不自动补发。',sites:'站点使用HTTPS。有关联产品不得删除；空商品站点不在C端占位。',products:'库存由未兑换卡密统计，不手填。下架/到期停止新兑换，历史兑换保留。确认时重查价格、库存和积分，无充值。',stock:'演示卡密仅使用占位符。重复入库阻止；已兑换库存不可删除，记录与兑换关联。',redemptions:'处理中查询原记录，不重复兑换。返还处理中不增加余额；按原积分批次期限返还，已过期部分不恢复可用。商品下架后成功记录与原演示码仍可查看复制。',points:'追加式积分流水，不提供任意发分或编辑账目。预占、结算、释放分开；活动待发不等于到账。返还不延长有效期。',checkin:'北京时间自然周一至周日，断签或跨周重计连续进度，无补签。奖励满足规则自动到账；运营维护计划不改历史流水。',invite:'新旧未绑定账号均可补绑，无注册后期限。禁止自邀、重复绑定；首次成功关系不换绑/解绑。阶段、配额与结算独立；异常人工核验，不新增复杂自动风控或任意发奖。'};
const types:Record<Bucket,string[]>={circles:['圈子'],topics:['专题'],taxonomy:['作品分类','帖子分类','教程分类','应用分类','内容话题','使用场景','模板模型','教程标签'],features:['作品推荐','帖子推荐','应用排序','应用推荐','专题推荐','推荐词'],slots:['首页 Banner','金刚区','推荐位'],events:['long_term','campaign','referral'],submissions:['作品','帖子'],sites:['站点'],products:['卡密商品'],stock:['演示卡密'],redemptions:['卡密兑换'],points:['活动奖励','生成预占','兑换扣减','生成结算','释放','返还','签到奖励','邀请奖励'],checkin:['自然周计划','签到记录'],invite:['邀请规则','邀请关系']};
const str=(v:unknown)=>{if(v==null)return '';if(typeof v==='string')return v;if(typeof v==='number'||typeof v==='boolean'||typeof v==='bigint')return v.toString();return JSON.stringify(v)||'';};
