 function eventFields(){return <Tabs activeKey={eventTab} onChange={setEventTab} items={[{key:'base',label:'基础配置',forceRender:true,children:<><div className="om-form-grid"><Form.Item name="name" label="活动名称" rules={[{required:true,whitespace:true}]}><Input/></Form.Item><Form.Item name="code" label="唯一编码" rules={[{required:true},{pattern:/^[a-z0-9_]+$/,message:'小写英文、数字和下划线'}]}><Input disabled={editor?.id!=='new'}/></Form.Item><Form.Item name="type" label="活动类型" rules={[{required:true}]}><Select options={[{label:'长期活动',value:'long_term'},{label:'档期活动',value:'campaign'},{label:'邀请活动',value:'referral'}]}/></Form.Item><Form.Item name="status" label="公开状态"><Select options={opts(['草稿','进行中','已结束'])}/></Form.Item><Form.Item name="max_points" label="展示最高积分"><InputNumber min={0} precision={0}/></Form.Item><Form.Item name="sort_order" label="活动顺序"><InputNumber min={0} precision={0}/></Form.Item></div><Form.Item name="range" label="活动起止时间（北京时间；结束时刻不含）"><DatePicker.RangePicker showTime/></Form.Item><Form.Item name="cover_url" label="封面" rules={[{required:true}]}><CoverUpload /></Form.Item><Form.Item name="is_featured" label="主推活动" valuePropName="checked"><Switch/></Form.Item><Form.Item name="description" hidden><Input/></Form.Item><Form.Item label="Markdown活动说明"><Form.Item noStyle shouldUpdate>{()=> <div ><MarkdownEditor value={str(form.getFieldValue('description'))} onChange={text=>{form.setFieldValue('description',text);setDirty(true)}}/></div>}</Form.Item></Form.Item></>},{key:'rules',label:'资格与投稿规则',forceRender:true,children:<><Form.Item name="requires" label="前置活动"><Select mode="multiple" options={data.rows.events.filter(e=>e.id!==editor?.id).map(e=>({value:e.id,label:e.name}))}/></Form.Item><div className="om-form-grid"><Form.Item name="requiresCondition" label="前置条件" initialValue="all_completed"><Select options={[{value:'all_completed',label:'前置活动全部完成（自动发奖）'}]}/></Form.Item><Form.Item name="durationDays" label="个人有效天数"><InputNumber min={1} precision={0}/></Form.Item><Form.Item name="periodCode" label="依赖期次"><Input/></Form.Item><Form.Item name="nextCode" label="下游活动"><Select allowClear options={data.rows.events.filter(e=>e.id!==editor?.id).map(e=>({value:e.id,label:e.name}))}/></Form.Item><Form.Item name="bizType" label="投稿业务类型"><Select options={[{value:'work',label:'作品'},{value:'post',label:'帖子'},{value:'prompt',label:'Prompt'}]}/></Form.Item><Form.Item name="contentTypes" label="成果类型"><Select mode="multiple" options={[{value:2,label:'图片'},{value:3,label:'视频'},{value:4,label:'文本'}]}/></Form.Item><Form.Item name="minImages" label="最少图片数量"><InputNumber min={0} precision={0}/></Form.Item><Form.Item name="minVideos" label="最少视频数量"><InputNumber min={0} precision={0}/></Form.Item><Form.Item name="titleMin" label="标题最少字符"><InputNumber min={0} precision={0}/></Form.Item></div><Form.Item name="joinFirst" label="先参与再发布" valuePropName="checked"><Switch/></Form.Item><div className="om-form-grid"><Form.Item name="requiredTopic" label="必须指定话题" valuePropName="checked"><Switch/></Form.Item><Form.Item name="requiredCategory" label="必须指定分类" valuePropName="checked"><Switch/></Form.Item></div>{[['topicCodes','指定话题'],['categoryCodes','指定分类'],['modelCodes','指定模型'],['sceneCodes','指定场景']].map(([key,label])=><Form.Item key={key} name={key} label={label}><Select mode="tags" options={key==='categoryCodes'?data.rows.taxonomy.filter(c=>c.status==='启用').map(c=>({value:c.id,label:c.name})):[]}/></Form.Item>)}<div className="om-form-grid"><Form.Item name="quotaScope" label="邀请配额周期"><Select options={[{value:'per_day',label:'按日'},{value:'per_month',label:'按月'},{value:'per_period',label:'按期次'}]}/></Form.Item><Form.Item name="quotaLimit" label="邀请总配额次数"><InputNumber min={1} precision={0}/></Form.Item></div><Form.Item name="streak" label="连续里程碑配置"><Input.TextArea rows={5} placeholder={'{"timezone":"Asia/Shanghai","milestones":[{"days":3,"points":50}]}'}/></Form.Item><Alert type="info" title="任务分别配置自然日或参与后阶段开放；国庆活动固定10月1—7日，不从报名日起算，不补做。"/></>},{key:'tasks',label:`任务 (${tasks.length})`,children:<><Button onClick={()=>{const t=taskBlank(tasks.length);setTaskEdit(t);taskForm.setFieldsValue({...t,filterJson:'{}',validationJson:'{}'});}}>添加任务</Button><Table className="om-task-table" size="small" rowKey="task_code" dataSource={tasks} pagination={false} scroll={{x:720}} columns={[{title:'名称 / 编码',render:(_:unknown,t:EventTask)=><>{t.name||'未命名'}<div className="om-sub">{t.task_code}</div></>},{title:'事件',dataIndex:'event_type'},{title:'目标',dataIndex:'target_count'},{title:'积分 / 有效期',render:(_:unknown,t:EventTask)=>`${t.reward_points} / ${t.expire_days}天`},{title:'发放',render:(_:unknown,t:EventTask)=>({realtime:'实时自动',deferred:'延后自动',manual:'人工核验'}[t.reward_dispatch_mode])},{title:'操作',render:(_:unknown,t:EventTask)=><Space><Button type="link" onClick={()=>{setTaskEdit(t);taskForm.resetFields();taskForm.setFieldsValue({...t,quotaScope:t.quota_rule.scope,quotaLimit:t.quota_rule.limit,filterJson:JSON.stringify(t.event_filter,null,2),validationJson:JSON.stringify(t.validation_rule,null,2)});}}>编辑</Button><Button type="link" danger disabled={['invite.register','invite.interact','invite.publish'].includes(t.event_type)} onClick={()=>confirm('删除任务？','未完成任务受影响，现有积分流水不删除。',()=>{setTasks(tasks.filter(x=>x.task_code!==t.task_code));setDirty(true)})}>删除</Button></Space>}]} /></>}]} />;}
 function detailBody(r:OpRow){return <><Descriptions bordered column={1} size="small" items={[...(r.type==='签到记录'&&!r.user?[{key:'user',label:'用户',children:<UserIdentity id={r.name}/>}]:[]),{key:'id',label:'稳定标识',children:r.id},{key:'status',label:'状态',children:publicStateLabel(bucket,r.status)},{key:'type',label:'类型',children:r.type},...Object.entries(r).filter(([k])=>k!=='owner'&&!['id','name','status','type','config','publicSnapshot','material','order','liveRefs','published','draftPending','pins','postIds','removedPosts','contentCircle'].includes(k)).map(([k,v])=>({key:k,label:({summary:'说明',user:'用户',inviter:'邀请人',invitee:'被邀请人',owner:'负责人',price:'实扣积分',source:'关联业务',eligibility:'资格',review:'评审',reward:'奖励',reason:'可读原因',at:'时间',returnAmount:'返还总额',availableReturn:'恢复可用',expiredReturn:'原积分已过期',originalExpiry:'原批次到期',code:'演示卡密',refs:r.id==='ft-work'?'入选作品':'引用顺序',pins:'置顶顺序',expires:'积分到期',points:'积分'} as Record<string,string>)[k]||k,children:['user','inviter','invitee','owner'].includes(k)?<UserIdentity id={str(v)}/>:typeof v==='object'?JSON.stringify(v):str(v)||'—'}))]}/>{bucket==='events'&&<><h3>结构化任务</h3><Table size="small" rowKey="task_code" pagination={false} dataSource={(r.config as EventConfig).tasks} columns={[{title:'任务',dataIndex:'name'},{title:'目标',dataIndex:'target_count'},{title:'积分',dataIndex:'reward_points'},{title:'有效天数',dataIndex:'expire_days'}]}/><h3>活动说明</h3><ContentBlockPreview block={{id:'activity-description',type:'Markdown',text:(r.config as EventConfig).description}}/></>}{bucket==='redemptions'&&<><Alert className="om-gap" type={r.status==='成功'?'success':'warning'} title={r.status==='成功'?'原成功兑换结果可查看、复制':'查询原兑换记录，不重复消耗库存或积分'}/>{r.status==='成功'&&<Button onClick={async()=>{try{await navigator.clipboard.writeText(str(r.code));message.success('已复制演示占位码')}catch{message.warning('复制不可用，请手动选取演示码')}}}>复制演示码</Button>}<Button className="om-gap" onClick={()=>message.info('原记录状态：'+r.status+'；未创建新兑换或改账')}>查询原记录</Button>{r.status!=='成功'&&<Button disabled={denied} onClick={()=>{let reason='';modal.confirm({title:'登记人工核查',content:<Input.TextArea placeholder="核查依据和可读说明" onChange={e=>reason=e.target.value}/>,onOk:()=>{if(!reason.trim())return Promise.reject(new Error('填写核查说明'));const next={...r,reason:reason.trim()};if(update(next,'登记核查','关联原兑换，不模拟到账或返还完成'))setDetail(next);}})}}>登记核查</Button>}</>}{bucket==='invite'&&r.type==='邀请关系'&&<Button disabled={denied} onClick={()=>{let reason='';modal.confirm({title:'记录邀请人工核验',content:<Input.TextArea placeholder="有效事件与核验说明，不变更邀请关系或账目" onChange={e=>reason=e.target.value}/>,onOk:()=>{if(!reason.trim())return Promise.reject(new Error('填写说明'));const next={...r,reason};if(update(next,'保存人工核验','保留原关系与积分流水'))setDetail(next)}})}}>记录人工核验</Button>}</>;}
